package org.eclipse.rdf4j.query.algebra.evaluation.iterator;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.common.iteration.CloseableIteratorIteration;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.Dataset;
import org.eclipse.rdf4j.query.algebra.LeftJoin;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryBindingSet;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryEvaluationStep;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.QueryEvaluationContext;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.HashJoinBindingContract;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

/**
 * The residual condition of {@link HashJoinIteration} implements the SPARQL LeftJoin rule that a left row survives
 * alone exactly when no compatible optional row satisfies the condition, which a post-filter on the join output could
 * not express (it would drop the left row altogether).
 */
class HashJoinIterationResidualConditionTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final Value ONE = VF.createLiteral(1);
	private static final Value TWO = VF.createLiteral(2);
	private static final Value KEEP = VF.createLiteral("keep");
	private static final Value DROP = VF.createLiteral("drop");
	private static final Predicate<BindingSet> KEEP_ONLY = row -> KEEP.equals(row.getValue("y"));

	@Test
	void leftJoinResidualKeepsPassingCandidatesAndEmitsBareProbeRowsOtherwise() {
		List<BindingSet> probe = List.of(row("x", ONE), row("x", TWO));
		List<BindingSet> build = List.of(row("x", ONE, "y", KEEP), row("x", ONE, "y", DROP), row("x", TWO, "y", DROP));
		LeftJoin joinNode = new LeftJoin(new SingletonSet(), new SingletonSet());
		joinNode.setRuntimeTelemetryEnabled(true);

		List<BindingSet> results = evaluate(probe, build, true, KEEP_ONLY, joinNode);

		assertThat(results).hasSize(2);
		assertThat(results.get(0).getValue("x")).isEqualTo(ONE);
		assertThat(results.get(0).getValue("y")).as("only the candidate that satisfies the residual is joined")
				.isEqualTo(KEEP);
		assertThat(results.get(1).getValue("x")).isEqualTo(TWO);
		assertThat(results.get(1).hasBinding("y")).as("a probe row whose candidates all fail survives alone").isFalse();
		assertThat(joinNode.getLongMetricActual("actualCostHashBuildRows")).isEqualTo(3L);
		assertThat(joinNode.getLongMetricActual("actualCostHashProbeInputRows")).isEqualTo(2L);
		assertThat(joinNode.getLongMetricActual("actualCostHashCandidateRows"))
				.as("candidates the residual rejects still count as probed candidates")
				.isEqualTo(3L);
	}

	@Test
	void leftJoinResidualSeesTheMergedRow() {
		List<BindingSet> probe = List.of(row("x", ONE, "left", KEEP), row("x", TWO, "left", DROP));
		List<BindingSet> build = List.of(row("x", ONE, "y", KEEP), row("x", TWO, "y", KEEP));
		Predicate<BindingSet> bothSides = row -> row.getValue("left") != null && row.getValue("y") != null
				&& row.getValue("left").equals(row.getValue("y"));

		List<BindingSet> results = evaluate(probe, build, true, bothSides, null);

		assertThat(results).hasSize(2);
		assertThat(results.get(0).getValue("y")).isEqualTo(KEEP);
		assertThat(results.get(1).hasBinding("y")).isFalse();
	}

	@Test
	void leftJoinWithoutMatchesIgnoresTheResidual() {
		List<BindingSet> probe = List.of(row("x", ONE));
		List<BindingSet> build = List.of(row("x", TWO, "y", KEEP));

		List<BindingSet> results = evaluate(probe, build, true, ignored -> {
			throw new AssertionError("no candidate, nothing to test");
		}, null);

		assertThat(results).hasSize(1);
		assertThat(results.get(0).getValue("x")).isEqualTo(ONE);
		assertThat(results.get(0).hasBinding("y")).isFalse();
	}

	@Test
	void partiallyBoundBuildRowsGoThroughTheResidual() {
		List<BindingSet> probe = List.of(row("x", ONE));
		// the build row does not bind the lookup attribute and is found through the partial-key index
		List<BindingSet> build = List.of(row("y", KEEP), row("y", DROP));

		List<BindingSet> results = evaluate(probe, build, true, KEEP_ONLY, null);

		assertThat(results).hasSize(1);
		assertThat(results.get(0).getValue("x")).isEqualTo(ONE);
		assertThat(results.get(0).getValue("y")).isEqualTo(KEEP);
	}

	@Test
	void innerJoinResidualDropsFailingRowsWithoutBareRows() {
		List<BindingSet> probe = List.of(row("x", ONE), row("x", TWO));
		List<BindingSet> build = List.of(row("x", ONE, "y", KEEP), row("x", TWO, "y", DROP));

		List<BindingSet> results = evaluate(probe, build, false, KEEP_ONLY, null);

		assertThat(results).hasSize(1);
		assertThat(results.get(0).getValue("x")).isEqualTo(ONE);
		assertThat(results.get(0).getValue("y")).isEqualTo(KEEP);
	}

	private static List<BindingSet> evaluate(List<BindingSet> probe, List<BindingSet> build, boolean leftJoin,
			Predicate<BindingSet> residual, LeftJoin joinNode) {
		QueryEvaluationStep left = ignored -> new CloseableIteratorIteration<>(new ArrayList<>(probe).iterator());
		QueryEvaluationStep right = ignored -> new CloseableIteratorIteration<>(new ArrayList<>(build).iterator());
		HashJoinBindingContract contract = HashJoinBindingContract.legacy(new String[] { "x" });
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		List<BindingSet> results = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = new HashJoinIteration(left, right,
				EmptyBindingSet.getInstance(), leftJoin, contract, context, HashJoinIteration.BuildSide.RIGHT, joinNode,
				residual)) {
			while (iteration.hasNext()) {
				results.add(iteration.next());
			}
			assertThat(iteration.hasNext()).isFalse();
		}
		return results;
	}

	private static BindingSet row(String name, Value value) {
		QueryBindingSet row = new QueryBindingSet(1);
		row.addBinding(name, value);
		return row;
	}

	private static BindingSet row(String name, Value value, String otherName, Value otherValue) {
		QueryBindingSet row = new QueryBindingSet(2);
		row.addBinding(name, value);
		row.addBinding(otherName, otherValue);
		return row;
	}
}
